CREATE TABLE IF NOT EXISTS "accounts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public handle used in the URL. Stored lowercase so uniqueness is case-insensitive.
	"username" VARCHAR(30) NOT NULL UNIQUE,
	-- Display name. Free text, not unique, and not used for lookup.
	"full_name" VARCHAR(80),
	-- Profile blurb rendered under the avatar.
	"bio" VARCHAR(300),
	-- CDN URL of the profile picture. A URL rather than a media row because there is only ever one.
	"avatar_url" VARCHAR(500),
	-- When true a new follow lands as pending instead of accepted. This single flag is what forks the whole follow flow.
	"is_private" BOOLEAN NOT NULL DEFAULT false,
	-- Identity confirmed by the platform; purely a badge.
	"is_verified" BOOLEAN NOT NULL DEFAULT false,
	-- Denormalised count of accepted inbound follows. Maintained by trigger or worker because profile pages would otherwise COUNT a multi-million-row table on every view.
	"follower_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised count of accepted outbound follows.
	"following_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised count of non-deleted posts.
	"post_count" INTEGER NOT NULL DEFAULT 0,
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "accounts" IS 'A person. The three counter columns are deliberate denormalisation: they are read on every profile render and written far less often than they are read.';
COMMENT ON COLUMN "accounts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "accounts"."username" IS 'Public handle used in the URL. Stored lowercase so uniqueness is case-insensitive.';
COMMENT ON COLUMN "accounts"."full_name" IS 'Display name. Free text, not unique, and not used for lookup.';
COMMENT ON COLUMN "accounts"."bio" IS 'Profile blurb rendered under the avatar.';
COMMENT ON COLUMN "accounts"."avatar_url" IS 'CDN URL of the profile picture. A URL rather than a media row because there is only ever one.';
COMMENT ON COLUMN "accounts"."is_private" IS 'When true a new follow lands as pending instead of accepted. This single flag is what forks the whole follow flow.';
COMMENT ON COLUMN "accounts"."is_verified" IS 'Identity confirmed by the platform; purely a badge.';
COMMENT ON COLUMN "accounts"."follower_count" IS 'Denormalised count of accepted inbound follows. Maintained by trigger or worker because profile pages would otherwise COUNT a multi-million-row table on every view.';
COMMENT ON COLUMN "accounts"."following_count" IS 'Denormalised count of accepted outbound follows.';
COMMENT ON COLUMN "accounts"."post_count" IS 'Denormalised count of non-deleted posts.';
COMMENT ON COLUMN "accounts"."created_at" IS 'Signup time.';

CREATE INDEX "idx_accounts_created_at"
ON "accounts" ("created_at");

CREATE TABLE IF NOT EXISTS "follows" (
	-- Account doing the following.
	"follower_id" BIGINT,
	-- Account being followed. The pair is the primary key, so the same follow cannot be recorded twice.
	"followee_id" BIGINT,
	-- pending | accepted. Pending exists only when the followee is private; public accounts skip straight to accepted.
	"status" VARCHAR(12) NOT NULL DEFAULT 'accepted',
	-- When the follow or request was created. Sorts the pending-requests inbox.
	"requested_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When a private account approved the request. Null while pending, and for follows that never needed approval.
	"responded_at" TIMESTAMP,
	PRIMARY KEY("follower_id", "followee_id")
);

COMMENT ON TABLE "follows" IS 'Directed edge: following someone says nothing about them following back. Both directions are indexed because the two questions - who follows me, whose posts do I read - are asked equally often.';
COMMENT ON COLUMN "follows"."follower_id" IS 'Account doing the following.';
COMMENT ON COLUMN "follows"."followee_id" IS 'Account being followed. The pair is the primary key, so the same follow cannot be recorded twice.';
COMMENT ON COLUMN "follows"."status" IS 'pending | accepted. Pending exists only when the followee is private; public accounts skip straight to accepted.';
COMMENT ON COLUMN "follows"."requested_at" IS 'When the follow or request was created. Sorts the pending-requests inbox.';
COMMENT ON COLUMN "follows"."responded_at" IS 'When a private account approved the request. Null while pending, and for follows that never needed approval.';

CREATE INDEX "idx_follows_followee_status"
ON "follows" ("followee_id", "status");
CREATE INDEX "idx_follows_follower_status"
ON "follows" ("follower_id", "status");

CREATE TABLE IF NOT EXISTS "posts" (
	-- Surrogate primary key. Monotonic, so it doubles as a stable feed cursor.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that published the post.
	"author_id" BIGINT NOT NULL,
	-- Caption text including hashtags as typed. Null for a caption-less post.
	"caption" VARCHAR(2200),
	-- Place label shown above the media. Free text rather than a places table, which keeps tagging from depending on a gazetteer.
	"location_name" VARCHAR(120),
	-- Latitude of the tagged place. Null when no place was tagged.
	"latitude" NUMERIC(9,6),
	-- Longitude of the tagged place.
	"longitude" NUMERIC(9,6),
	-- Denormalised like total. The feed shows it on every card; counting rows per card is not survivable.
	"like_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised comment total, top-level plus replies.
	"comment_count" INTEGER NOT NULL DEFAULT 0,
	-- Author can close a post to new comments without hiding the existing ones.
	"comments_enabled" BOOLEAN NOT NULL DEFAULT true,
	-- Publication time. Paired with author_id it is the index the feed query lives on.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Soft delete. Set rather than removing the row so that in-flight notifications and saved-collection entries degrade instead of dangling.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "posts" IS 'One post, whatever the number of attachments. The feed is read by pulling the most recent posts of the accounts you follow and merging them, which is why (author_id, created_at) is the only index that matters.';
COMMENT ON COLUMN "posts"."id" IS 'Surrogate primary key. Monotonic, so it doubles as a stable feed cursor.';
COMMENT ON COLUMN "posts"."author_id" IS 'Account that published the post.';
COMMENT ON COLUMN "posts"."caption" IS 'Caption text including hashtags as typed. Null for a caption-less post.';
COMMENT ON COLUMN "posts"."location_name" IS 'Place label shown above the media. Free text rather than a places table, which keeps tagging from depending on a gazetteer.';
COMMENT ON COLUMN "posts"."latitude" IS 'Latitude of the tagged place. Null when no place was tagged.';
COMMENT ON COLUMN "posts"."longitude" IS 'Longitude of the tagged place.';
COMMENT ON COLUMN "posts"."like_count" IS 'Denormalised like total. The feed shows it on every card; counting rows per card is not survivable.';
COMMENT ON COLUMN "posts"."comment_count" IS 'Denormalised comment total, top-level plus replies.';
COMMENT ON COLUMN "posts"."comments_enabled" IS 'Author can close a post to new comments without hiding the existing ones.';
COMMENT ON COLUMN "posts"."created_at" IS 'Publication time. Paired with author_id it is the index the feed query lives on.';
COMMENT ON COLUMN "posts"."deleted_at" IS 'Soft delete. Set rather than removing the row so that in-flight notifications and saved-collection entries degrade instead of dangling.';

CREATE INDEX "idx_posts_author_created"
ON "posts" ("author_id", "created_at");

CREATE TABLE IF NOT EXISTS "post_media" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Post this attachment belongs to.
	"post_id" BIGINT NOT NULL,
	-- Zero-based slot in the carousel. Unique per post, which is what stops two images claiming the same slide.
	"position" SMALLINT NOT NULL,
	-- image | video. Decides which player the client mounts.
	"media_type" VARCHAR(12) NOT NULL,
	-- Object-store key of the original upload. Derivatives are addressed by convention from it, so resizing does not need rows.
	"storage_key" VARCHAR(400) NOT NULL,
	-- Pixel width of the original, used to reserve layout space before the bytes arrive.
	"width" INTEGER NOT NULL,
	-- Pixel height of the original.
	"height" INTEGER NOT NULL,
	-- Playback length for video. Null for images.
	"duration_ms" INTEGER,
	-- Accessibility description, author-written or generated.
	"alt_text" VARCHAR(1000),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "post_media" IS 'One row per attachment rather than an array column on posts. Each slide has its own dimensions, duration, alt text and moderation outcome, and only rows let you index, join and delete a single slide.';
COMMENT ON COLUMN "post_media"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "post_media"."post_id" IS 'Post this attachment belongs to.';
COMMENT ON COLUMN "post_media"."position" IS 'Zero-based slot in the carousel. Unique per post, which is what stops two images claiming the same slide.';
COMMENT ON COLUMN "post_media"."media_type" IS 'image | video. Decides which player the client mounts.';
COMMENT ON COLUMN "post_media"."storage_key" IS 'Object-store key of the original upload. Derivatives are addressed by convention from it, so resizing does not need rows.';
COMMENT ON COLUMN "post_media"."width" IS 'Pixel width of the original, used to reserve layout space before the bytes arrive.';
COMMENT ON COLUMN "post_media"."height" IS 'Pixel height of the original.';
COMMENT ON COLUMN "post_media"."duration_ms" IS 'Playback length for video. Null for images.';
COMMENT ON COLUMN "post_media"."alt_text" IS 'Accessibility description, author-written or generated.';

CREATE UNIQUE INDEX "uq_post_media_post_position"
ON "post_media" ("post_id", "position");

CREATE TABLE IF NOT EXISTS "post_likes" (
	-- Post that was liked.
	"post_id" BIGINT,
	-- Account that liked it. The composite key makes double-liking impossible without an extra uniqueness index.
	"account_id" BIGINT,
	-- When the like happened; orders the liker list and the resulting notification.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("post_id", "account_id")
);

COMMENT ON TABLE "post_likes" IS 'The narrowest table in the schema and one of the largest. It carries no surrogate id because nothing ever references a like; the pair is the identity.';
COMMENT ON COLUMN "post_likes"."post_id" IS 'Post that was liked.';
COMMENT ON COLUMN "post_likes"."account_id" IS 'Account that liked it. The composite key makes double-liking impossible without an extra uniqueness index.';
COMMENT ON COLUMN "post_likes"."created_at" IS 'When the like happened; orders the liker list and the resulting notification.';

CREATE INDEX "idx_post_likes_account_created"
ON "post_likes" ("account_id", "created_at");

CREATE TABLE IF NOT EXISTS "comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Post being commented on. Denormalised onto replies too, so a post loads its whole comment section with one range scan.
	"post_id" BIGINT NOT NULL,
	-- Account that wrote the comment.
	"author_id" BIGINT NOT NULL,
	-- Top-level comment this replies to. Null for a top-level comment. Replies to replies are re-parented to the same top-level comment, so the tree is exactly two levels deep.
	"parent_comment_id" BIGINT,
	-- Comment text as typed, mentions included.
	"body" VARCHAR(2200) NOT NULL,
	-- Denormalised like total; comment likes are not stored per row in this model.
	"like_count" INTEGER NOT NULL DEFAULT 0,
	-- Posting time, the sort key within a thread.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "comments" IS 'A comment thread capped at two levels. Flattening deeper replies is a product decision that buys a bounded query: one scan for top-level comments, one for the replies of the ones on screen.';
COMMENT ON COLUMN "comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "comments"."post_id" IS 'Post being commented on. Denormalised onto replies too, so a post loads its whole comment section with one range scan.';
COMMENT ON COLUMN "comments"."author_id" IS 'Account that wrote the comment.';
COMMENT ON COLUMN "comments"."parent_comment_id" IS 'Top-level comment this replies to. Null for a top-level comment. Replies to replies are re-parented to the same top-level comment, so the tree is exactly two levels deep.';
COMMENT ON COLUMN "comments"."body" IS 'Comment text as typed, mentions included.';
COMMENT ON COLUMN "comments"."like_count" IS 'Denormalised like total; comment likes are not stored per row in this model.';
COMMENT ON COLUMN "comments"."created_at" IS 'Posting time, the sort key within a thread.';

CREATE INDEX "idx_comments_post_created"
ON "comments" ("post_id", "created_at");
CREATE INDEX "idx_comments_parent_created"
ON "comments" ("parent_comment_id", "created_at");

CREATE TABLE IF NOT EXISTS "stories" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that posted the story.
	"author_id" BIGINT NOT NULL,
	-- image | video.
	"media_type" VARCHAR(12) NOT NULL,
	-- Object-store key of the uploaded frame or clip.
	"storage_key" VARCHAR(400) NOT NULL,
	-- How long the frame is held before advancing. Images get a default, videos their real length.
	"duration_ms" INTEGER NOT NULL DEFAULT 5000,
	-- Posting time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When the story leaves the tray, normally created_at plus 24 hours. Stored rather than computed so the window can be changed per story without rewriting the read query.
	"expires_at" TIMESTAMP NOT NULL,
	-- Set when the author pins the story to a profile highlight, which is what lets it outlive expires_at.
	"highlight_name" VARCHAR(60),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "stories" IS 'Ephemeral media. Expiry is a column, not a delete: the row survives for the author archive and for highlights, and the tray query simply filters on expires_at > now().';
COMMENT ON COLUMN "stories"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "stories"."author_id" IS 'Account that posted the story.';
COMMENT ON COLUMN "stories"."media_type" IS 'image | video.';
COMMENT ON COLUMN "stories"."storage_key" IS 'Object-store key of the uploaded frame or clip.';
COMMENT ON COLUMN "stories"."duration_ms" IS 'How long the frame is held before advancing. Images get a default, videos their real length.';
COMMENT ON COLUMN "stories"."created_at" IS 'Posting time.';
COMMENT ON COLUMN "stories"."expires_at" IS 'When the story leaves the tray, normally created_at plus 24 hours. Stored rather than computed so the window can be changed per story without rewriting the read query.';
COMMENT ON COLUMN "stories"."highlight_name" IS 'Set when the author pins the story to a profile highlight, which is what lets it outlive expires_at.';

CREATE INDEX "idx_stories_author_expires"
ON "stories" ("author_id", "expires_at");

CREATE TABLE IF NOT EXISTS "story_views" (
	-- Story that was seen.
	"story_id" BIGINT,
	-- Account that saw it.
	"viewer_id" BIGINT,
	-- First view. Re-watching does not append a row, because the product only shows a distinct viewer list.
	"viewed_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("story_id", "viewer_id")
);

COMMENT ON TABLE "story_views" IS 'The viewer list an author sees on their own story. Write-heavy and short-lived - rows are reaped with the story once the archive window closes.';
COMMENT ON COLUMN "story_views"."story_id" IS 'Story that was seen.';
COMMENT ON COLUMN "story_views"."viewer_id" IS 'Account that saw it.';
COMMENT ON COLUMN "story_views"."viewed_at" IS 'First view. Re-watching does not append a row, because the product only shows a distinct viewer list.';

CREATE TABLE IF NOT EXISTS "collections" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that owns the collection. Collections are always private to their owner.
	"owner_id" BIGINT NOT NULL,
	-- Folder name shown in the saved tab.
	"name" VARCHAR(60) NOT NULL,
	-- Marks the implicit "All posts" collection created at signup, so a plain save never has to ask which folder.
	"is_default" BOOLEAN NOT NULL DEFAULT false,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "collections" IS 'A private folder of saved posts. Saving is modelled as collection membership rather than a flag on the post, so the same post can sit in several folders.';
COMMENT ON COLUMN "collections"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "collections"."owner_id" IS 'Account that owns the collection. Collections are always private to their owner.';
COMMENT ON COLUMN "collections"."name" IS 'Folder name shown in the saved tab.';
COMMENT ON COLUMN "collections"."is_default" IS 'Marks the implicit "All posts" collection created at signup, so a plain save never has to ask which folder.';
COMMENT ON COLUMN "collections"."created_at" IS 'Creation time.';

CREATE UNIQUE INDEX "uq_collections_owner_name"
ON "collections" ("owner_id", "name");

CREATE TABLE IF NOT EXISTS "collection_saves" (
	-- Collection the post was filed under.
	"collection_id" BIGINT,
	-- Post that was saved.
	"post_id" BIGINT,
	-- When it was filed; the saved tab is ordered by this, not by the post date.
	"saved_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("collection_id", "post_id")
);

COMMENT ON TABLE "collection_saves" IS 'Join between collections and posts. The author is never told, which is why this table has no notification side effects anywhere in the schema.';
COMMENT ON COLUMN "collection_saves"."collection_id" IS 'Collection the post was filed under.';
COMMENT ON COLUMN "collection_saves"."post_id" IS 'Post that was saved.';
COMMENT ON COLUMN "collection_saves"."saved_at" IS 'When it was filed; the saved tab is ordered by this, not by the post date.';

CREATE TABLE IF NOT EXISTS "direct_threads" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- One-to-one threads and group threads share this table; the flag only changes how the header renders.
	"is_group" BOOLEAN NOT NULL DEFAULT false,
	-- Group name. Null for one-to-one threads, which are titled from the other participant.
	"title" VARCHAR(80),
	-- Thread opened by someone the recipient does not follow. It sits in a separate inbox until accepted, which is the messaging mirror of a pending follow.
	"is_request" BOOLEAN NOT NULL DEFAULT false,
	-- Account that started the thread. Null once that account is deleted.
	"created_by_id" BIGINT,
	-- Timestamp of the newest message, denormalised so the inbox sorts without touching the message table.
	"last_message_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "direct_threads" IS 'A conversation. last_message_at is the one piece of message state kept here, because the inbox list is read far more often than any thread is opened.';
COMMENT ON COLUMN "direct_threads"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "direct_threads"."is_group" IS 'One-to-one threads and group threads share this table; the flag only changes how the header renders.';
COMMENT ON COLUMN "direct_threads"."title" IS 'Group name. Null for one-to-one threads, which are titled from the other participant.';
COMMENT ON COLUMN "direct_threads"."is_request" IS 'Thread opened by someone the recipient does not follow. It sits in a separate inbox until accepted, which is the messaging mirror of a pending follow.';
COMMENT ON COLUMN "direct_threads"."created_by_id" IS 'Account that started the thread. Null once that account is deleted.';
COMMENT ON COLUMN "direct_threads"."last_message_at" IS 'Timestamp of the newest message, denormalised so the inbox sorts without touching the message table.';

CREATE INDEX "idx_direct_threads_last_message"
ON "direct_threads" ("last_message_at");

CREATE TABLE IF NOT EXISTS "direct_thread_members" (
	-- Thread being joined.
	"thread_id" BIGINT,
	-- Participant.
	"account_id" BIGINT,
	-- When they were added. Messages older than this are still visible in this model; hiding them would need a per-member floor.
	"joined_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Newest message this member has read. Unread badges are a comparison against the thread head rather than a per-message receipt table.
	"last_read_message_id" BIGINT,
	-- Suppresses push notifications without leaving the thread.
	"is_muted" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("thread_id", "account_id")
);

COMMENT ON TABLE "direct_thread_members" IS 'Membership of a conversation. Read state lives here, one row per member, instead of one row per member per message.';
COMMENT ON COLUMN "direct_thread_members"."thread_id" IS 'Thread being joined.';
COMMENT ON COLUMN "direct_thread_members"."account_id" IS 'Participant.';
COMMENT ON COLUMN "direct_thread_members"."joined_at" IS 'When they were added. Messages older than this are still visible in this model; hiding them would need a per-member floor.';
COMMENT ON COLUMN "direct_thread_members"."last_read_message_id" IS 'Newest message this member has read. Unread badges are a comparison against the thread head rather than a per-message receipt table.';
COMMENT ON COLUMN "direct_thread_members"."is_muted" IS 'Suppresses push notifications without leaving the thread.';

CREATE TABLE IF NOT EXISTS "direct_messages" (
	-- Surrogate primary key, monotonic so it orders messages and doubles as the read cursor.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Thread the message belongs to.
	"thread_id" BIGINT NOT NULL,
	-- Author of the message.
	"sender_id" BIGINT NOT NULL,
	-- Text content. Null when the message is only a shared post or a reaction.
	"body" VARCHAR(2000),
	-- Post forwarded into the conversation. Sharing a post is a message, not a separate feature, which is why it is a column here.
	"shared_post_id" BIGINT,
	-- Message being replied to inside the thread. Null for a plain message.
	"reply_to_message_id" BIGINT,
	-- Send time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "direct_messages" IS 'Messages, read as a descending range scan on (thread_id, id). Paging by id rather than timestamp avoids the duplicate-row problem two messages sent in the same millisecond would cause.';
COMMENT ON COLUMN "direct_messages"."id" IS 'Surrogate primary key, monotonic so it orders messages and doubles as the read cursor.';
COMMENT ON COLUMN "direct_messages"."thread_id" IS 'Thread the message belongs to.';
COMMENT ON COLUMN "direct_messages"."sender_id" IS 'Author of the message.';
COMMENT ON COLUMN "direct_messages"."body" IS 'Text content. Null when the message is only a shared post or a reaction.';
COMMENT ON COLUMN "direct_messages"."shared_post_id" IS 'Post forwarded into the conversation. Sharing a post is a message, not a separate feature, which is why it is a column here.';
COMMENT ON COLUMN "direct_messages"."reply_to_message_id" IS 'Message being replied to inside the thread. Null for a plain message.';
COMMENT ON COLUMN "direct_messages"."created_at" IS 'Send time.';

CREATE INDEX "idx_direct_messages_thread_id"
ON "direct_messages" ("thread_id", "id");

